");return-1;}returnstack->items[(stack->top)--];}// Function to get the top element of the stackintpeek(structStack*stack){if(!isEmpty(stack)){returnstack->items[stack->top];}return-1;}// Function to find the next smaller element for every elementvoidnextSmaller(intarr[],intn,intnextS[]){structStack*stack=createStack(n);for(inti=0;i<n;i++){nextS[i]=n;}for(inti=0;i<n;i++){while(!isEmpty(stack)&&arr[i]<arr[peek(stack)]){nextS[peek(stack)]=i;pop(stack);}push(stack,i);}}// Function to find the previous smaller element for every elementvoidprevSmaller(intarr[],intn,intprevS[]){structStack*stack=createStack(n);for(inti=0;i<n;i++){prevS[i]=-1;}for(inti=0;i<n;i++){while(!isEmpty(stack)&&arr[i]<arr[peek(stack)]){pop(stack);}if(!isEmpty(stack)){prevS[i]=peek(stack);}push(stack,i);}}// Function to calculate the maximum rectangular// area in the HistogramintgetMaxArea(intarr[],intn){int*prevS=(int*)malloc(n*sizeof(int));int*nextS=(int*)malloc(n*sizeof(int));intmaxArea=0;// Find previous and next smaller elementsprevSmaller(arr,n,prevS);nextSmaller(arr,n,nextS);// Calculate the area for each arrogram barfor(inti=0;i<n;i++){intwidth=nextS[i]-prevS[i]-1;intarea=arr[i]*width;if(area>maxArea){maxArea=area;}}returnmaxArea;}// Driver codeintmain(){intarr[]={60,20,50,40,10,50,60};intn=sizeof(arr)/sizeof(arr[0]);printf("%d
",getMaxArea(arr,n));return0;}

